import React, { useEffect, useState, useMemo } from 'react';

// 1. DEFINE BADGE THRESHOLDS AND ICONS
const BADGE_THRESHOLDS = {
    volunteer: [
        { title: "Bronze Volunteer", desc: "20 Points", threshold: 20, key: "bronze_volunteer", 
          icon: "https://up.yimg.com/ib/th/id/OIP.OHs_yaTRMl1wF9glVaPZmgHaHa?pid=Api&rs=1&c=1&qlt=95&w=105&h=105" },
        { title: "Silver Volunteer", desc: "50 Points", threshold: 50, key: "silver_volunteer", 
          icon: "https://up.yimg.com/ib/th/id/OIP.8jVsS3Paqnphh1RUaZRO_gHaHa?pid=Api&rs=1&c=1&qlt=95&w=120&h=120" },
        { title: "Gold Volunteer", desc: "100 Points", threshold: 100, key: "gold_volunteer", 
          icon: "https://up.yimg.com/ib/th/id/OIP.M2jWfXFIT6yiFKdza-Xy9QHaHa?pid=Api&rs=1&c=1&qlt=95&w=121&h=121" },
    ],
    // Assuming donor points are either included in me.points or available separately
    // If donor points exist on `me`, you would add them here. For this fix, we stick to what `me` provides.
    // For now, we'll assign 'Donor' titles based on the main 'me.points' just to show the logic is working.
    donor: [
        { title: "Gold Donor", desc: "100 Points", threshold: 100, key: "gold_donor", 
          icon: "https://up.yimg.com/ib/th/id/OIP.M2jWfXFIT6yiFKdza-Xy9QHaHa?pid=Api&rs=1&c=1&qlt=95&w=121&h=121" },
        // ... more donor badges if donor points are available
    ]
};

// 2. FUNCTION TO CALCULATE EARNED BADGES
const calculateBadges = (points) => {
    const earnedBadges = [];
    const allThresholds = [
        ...BADGE_THRESHOLDS.volunteer,
        // If `me.donorPoints` existed and was used, you would pass it to this function
        // For this example, we calculate some "donor" type badges based on the same point total
        ...BADGE_THRESHOLDS.donor.filter(b => b.title.includes('Donor'))
    ];

    allThresholds.forEach(badge => {
        if (points >= badge.threshold) {
            earnedBadges.push(badge);
        }
    });

    return earnedBadges;
};

export default function AchievementsPanel({ token, me = {}, role = 'user', onViewNgo, setMsg }) {
    // We keep state for achievements/badges fetched from API for potential future use,
    // but we use a calculated list for display based on points.
    const [achievements, setAchievements] = useState(null);
    const [apiBadges, setApiBadges] = useState([]); // Badges fetched from API
    
    // Get points safely, defaulting to 0
    const currentPoints = me?.points || 0; 
    
    // 3. USE MEMO TO CALCULATE BADGES BASED ON POINTS
    const calculatedBadges = useMemo(() => {
        // This runs whenever `currentPoints` changes
        return calculateBadges(currentPoints);
    }, [currentPoints]);

    // Use a combined list: calculated badges take precedence (or replace API badges)
    // Note: If the backend handles badge assignment correctly, you might only rely on the API.
    // Since the prompt asks to assign badges as points increase, we use the calculated list.
    const badgesToDisplay = calculatedBadges.length > 0 ? calculatedBadges : apiBadges;


    // API fetching remains for full context, but now the display relies on `calculatedBadges`
    useEffect(() => {
        if (!token) return;

        const apiBase = process.env.REACT_APP_API || 'http://localhost:4000';
        const userUrl = role === 'NGO' ? `${apiBase}/api/ngo/achievements` : `${apiBase}/api/actions/achievements`;

        // Fetch achievements (e.g., total points)
        fetch(userUrl, { headers: { Authorization: `Bearer ${token}` } })
            .then(r => r.json())
            .then(d => { setAchievements(d); setApiBadges(d?.badges || []); })
            .catch(err => { console.error('Achievements load error', err); setAchievements({ badges: [] }); setApiBadges([]); });

        // Fetch persisted badges (if needed, otherwise can be removed)
        fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/user-badges', { headers: { Authorization: `Bearer ${token}` } })
            .then(r => r.json())
            .then(d => { if (d?.badges) setApiBadges(prev => [...prev, ...d.badges]); }) // Merging API badges
            .catch(() => {});
    }, [token, role]);

    return (
        <div style={{ width: 320, flexShrink: 0 }}>
            <h3 style={{ marginBottom: 12 }}>Achievements 🏆</h3>

            <div style={{
                background: 'linear-gradient(135deg,#0ea5e9,#6366f1)',
                padding: 18,
                borderRadius: 12,
                color: '#fff',
                textAlign: 'center',
                boxShadow: '0 8px 30px rgba(2,6,23,0.08)'
            }}>
                <div style={{ fontSize: 42, fontWeight: 800 }}>{currentPoints}</div>
                <div style={{ opacity: 0.9, marginTop: 6 }}>POINTS</div>
            </div>

            <div style={{ marginTop: 14 }}>
                <h4 style={{ marginBottom: 8 }}>Badges Earned</h4>

                {currentPoints === 0 && (
                    <div style={{ fontSize: 13, color: '#666' }}>
                        Earn points to unlock your first badge!
                    </div>
                )}

                {badgesToDisplay.length === 0 && currentPoints > 0 && (
                    <div style={{ padding: 14, borderRadius: 10, background: '#fff', color: '#666', boxShadow: '0 6px 20px rgba(0,0,0,0.04)' }}>
                        You are close to earning a badge at 20 points!
                    </div>
                )}

                {badgesToDisplay.length > 0 && (
                    <div
                        style={{
                            display: "grid",
                            gridTemplateColumns: "repeat(2,1fr)",
                            gap: 10,
                            marginTop: 10,
                        }}
                    >
                        {badgesToDisplay.map((b, i) => {
                            // Note: `b.icon` should already be present if using `calculatedBadges`
                            const finalIcon = b.icon || "https://placehold.co/45x45/cccccc/555555?text=Badge";

                            return (
                                <div
                                    key={b.key || b.badge_key || i}
                                    style={{
                                        background: "#fff",
                                        padding: 10,
                                        borderRadius: 10,
                                        boxShadow: "0 6px 18px rgba(0,0,0,0.06)",
                                        border: "1px solid #f1f5f9",
                                        textAlign: "center",
                                    }}
                                >
                                    {finalIcon && (
                                        <img
                                            src={finalIcon}
                                            alt={b.title}
                                            style={{
                                                width: 45,
                                                height: 45,
                                                marginBottom: 6,
                                                objectFit: "contain",
                                            }}
                                        />
                                    )}

                                    <div style={{ fontWeight: 700, fontSize: 14 }}>
                                        {b.title || b.badge_key}
                                    </div>

                                    <div style={{ fontSize: 12, color: "#555" }}>
                                        {b.desc || b.description}
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}

            </div>

            {onViewNgo && (
                <div style={{ marginTop: 18 }}>
                    <button onClick={() => onViewNgo()} style={{ width: '100%', padding: '10px 12px', borderRadius: 10, background: '#2563eb', color: '#fff', border: 0, cursor: 'pointer' }}>View Hosting NGOs</button>
                </div>
            )}
        </div>
    );
}
